UPDATE glossary SET achievement_id='89bd470d-e7fb-464b-874c-753f1d1db912' WHERE achievement_id='036e7ed0-94de-4228-9b97-4842a9f7fe95';
WITH noprim AS (SELECT glossary_id FROM glossary_topics GROUP BY glossary_id HAVING bool_or(is_primary) IS NOT TRUE),
pick AS (SELECT DISTINCT ON (glossary_id) id FROM glossary_topics WHERE glossary_id IN (SELECT glossary_id FROM noprim) ORDER BY glossary_id, id)
UPDATE glossary_topics SET is_primary=true WHERE id IN (SELECT id FROM pick);
COMMIT;